//! HTTP webhook channel for receiving messages via HTTP POST.use std::sync::Arc;use async_trait::async_trait;use axum::{    Json, Router,    extract::{DefaultBodyLimit, State},    http::{HeaderMap, StatusCode},    response::IntoResponse,    routing::{get, post},};use bytes::Bytes;use hmac::{Hmac, Mac};use secrecy::{ExposeSecret, SecretString};use serde::{Deserialize, Serialize};use sha2::Sha256;use subtle::ConstantTimeEq;use tokio::sync::{RwLock, mpsc, oneshot};use tokio_stream::wrappers::ReceiverStream;use uuid::Uuid;use crate::channels::{    AttachmentKind, Channel, ChannelSecretUpdater, IncomingAttachment, IncomingMessage,    MessageStream, OutgoingResponse,};use crate::config::HttpConfig;use crate::error::ChannelError;type HmacSha256 = Hmac<Sha256>;/// HTTP webhook channel.pub struct HttpChannel {    config: HttpConfig,    state: Arc<HttpChannelState>,}pub struct HttpChannelState {    /// Sender for incoming messages.    tx: RwLock<Option<mpsc::Sender<IncomingMessage>>>,    /// Pending responses keyed by message ID.    pending_responses: RwLock<std::collections::HashMap<Uuid, oneshot::Sender<String>>>,    /// Expected webhook secret for authentication (if configured).    /// Stored in a separate Arc<RwLock<>> to avoid contending with other state operations.    /// Rarely changes (only on SIGHUP), so isolated from hot-path state accesses.    /// Uses SecretString to prevent accidental logging and memory dump exposure.    webhook_secret: Arc<RwLock<Option<SecretString>>>,    /// Fixed user ID for this HTTP channel.    user_id: String,    /// Rate limiting state.    rate_limit: tokio::sync::Mutex<RateLimitState>,}#[derive(Debug)]struct RateLimitState {    window_start: std::time::Instant,    request_count: u32,}impl HttpChannelState {    /// Update the webhook secret in-place without restarting the listener.    /// Called during SIGHUP to hot-swap credentials.    pub async fn update_secret(&self, new_secret: Option<SecretString>) {        *self.webhook_secret.write().await = new_secret;    }}/// Maximum JSON body size for webhook requests (15 MB, to support base64 image attachments/// with ~33% overhead from base64 encoding).const MAX_BODY_BYTES: usize = 15 * 1024 * 1024;/// Maximum number of pending wait-for-response requests.const MAX_PENDING_RESPONSES: usize = 100;/// Maximum requests per minute.const MAX_REQUESTS_PER_MINUTE: u32 = 60;/// Maximum content length for a single message.const MAX_CONTENT_BYTES: usize = 32 * 1024;impl HttpChannel {    /// Create a new HTTP channel.    pub fn new(config: HttpConfig) -> Self {        let webhook_secret = config            .webhook_secret            .as_ref()            .map(|s| SecretString::from(s.expose_secret().to_string()));        let user_id = config.user_id.clone();        Self {            config,            state: Arc::new(HttpChannelState {                tx: RwLock::new(None),                pending_responses: RwLock::new(std::collections::HashMap::new()),                webhook_secret: Arc::new(RwLock::new(webhook_secret)),                user_id,                rate_limit: tokio::sync::Mutex::new(RateLimitState {                    window_start: std::time::Instant::now(),                    request_count: 0,                }),            }),        }    }    /// Return the channel's axum routes with state applied.    ///    /// The returned `Router` shares the same `Arc<HttpChannelState>` that    /// `start()` later populates. Before `start()` is called the webhook    /// handler returns 503 ("Channel not started").    pub fn routes(&self) -> Router {        Router::new()            .route("/health", get(health_handler))            .route("/webhook", post(webhook_handler))            .layer(DefaultBodyLimit::max(MAX_BODY_BYTES))            .with_state(self.state.clone())    }    /// Return the configured host and port for this channel.    pub fn addr(&self) -> (&str, u16) {        (&self.config.host, self.config.port)    }    /// Return a shared handle to the channel state for out-of-band updates.    pub fn shared_state(&self) -> Arc<HttpChannelState> {        Arc::clone(&self.state)    }    /// Update the webhook secret in-place without restarting the listener.    pub async fn update_secret(&self, new_secret: Option<SecretString>) {        self.state.update_secret(new_secret).await;    }}#[derive(Debug, Deserialize)]struct WebhookRequest {    /// User or client identifier (ignored, user is fixed by server config).    #[serde(default)]    user_id: Option<String>,    /// Message content.    content: String,    /// Optional thread ID for conversation tracking.    thread_id: Option<String>,    /// Deprecated: webhook secret in request body. Use X-Hub-Signature-256 header instead.    /// This field is accepted for backward compatibility but will be removed in a future release.    secret: Option<String>,    /// Whether to wait for a synchronous response.    #[serde(default)]    wait_for_response: bool,    /// Optional file attachments (base64-encoded).    #[serde(default)]    attachments: Vec<AttachmentData>,}/// A file attachment in a webhook request.#[derive(Debug, Deserialize)]struct AttachmentData {    /// MIME type (e.g. "image/png", "application/pdf").    mime_type: String,    /// Optional filename.    #[serde(default)]    filename: Option<String>,    /// Base64-encoded file data.    #[serde(default)]    data_base64: Option<String>,    /// URL to fetch the file from (not downloaded server-side for SSRF prevention).    #[serde(default)]    url: Option<String>,}/// Maximum size per attachment (5 MB decoded).const MAX_ATTACHMENT_BYTES: usize = 5 * 1024 * 1024;/// Maximum total attachment size (10 MB decoded).const MAX_TOTAL_ATTACHMENT_BYTES: usize = 10 * 1024 * 1024;/// Maximum number of attachments per request.const MAX_ATTACHMENTS: usize = 5;#[derive(Debug, Serialize)]struct WebhookResponse {    /// Message ID assigned to this request.    message_id: Uuid,    /// Status of the request.    status: String,    /// Response content (only if wait_for_response was true).    response: Option<String>,}#[derive(Debug, Serialize)]struct HealthResponse {    status: String,    channel: String,}async fn health_handler() -> impl IntoResponse {    Json(HealthResponse {        status: "healthy".to_string(),        channel: "http".to_string(),    })}/// Verify an HMAC-SHA256 signature against the raw request body.////// The expected header format is: `sha256=<hex_digest>`/// where the digest is HMAC-SHA256(secret_key, body_bytes) encoded as lowercase hex.fn verify_hmac_signature(secret: &str, body: &[u8], signature_header: &str) -> bool {    let hex_digest = match signature_header.strip_prefix("sha256=") {        Some(h) => h,        None => return false,    };    let provided_mac = match hex::decode(hex_digest) {        Ok(bytes) => bytes,        Err(_) => return false,    };    let mut mac = match HmacSha256::new_from_slice(secret.as_bytes()) {        Ok(mac) => mac,        Err(_) => return false,    };    mac.update(body);    let expected_mac = mac.finalize().into_bytes();    bool::from(expected_mac.as_slice().ct_eq(&provided_mac))}